            properties {
                name
                description

            }
        }
        ... on CorpUser {
            properties {
                fullName
                email
                __typename
            }
        }
        ... on GlossaryTerm {
            parentNodes {
                ...parentNodesFields
                __typename
            }
        }
        ...searchResultFields
    }
}

