            active
            displayName
            title
            firstName
            lastName
            fullName
            email
        }
    }
    ... on CorpGroup {
        name
        info {
            displayName
            description
        }
        memberCount: relationships(
            input: { types: ["IsMemberOfGroup", "IsMemberOfNativeGroup"], direction: INCOMING, start: 0, count: 1 }
        ) {
            total
        }
    }
    ... on Dashboard {
        dashboardId
        properties {
            name
            description
            externalUrl
            access
            lastModified {
                time
            }
        }
        ownership {
            ...ownershipFields
        }
        globalTags {
            ...globalTagsFields
        }
        glossaryTerms {
            ...glossaryTerms
        }
        platform {
            ...platformFields
        }
        dataPlatformInstance {
            ...dataPlatformInstanceFields
        }
        domain {
            ...entityDomain
        }
        ...entityDataProduct
        parentContainers {
            ...parentContainersFields
        }
        subTypes {
            typeNames
        }
    }
    ... on Chart {
        chartId
        properties {
            name
            description
            externalUrl
            type
            access
            lastModified {
                time
            }
            created {
                time
            }
        }
        ownership {
            ...ownershipFields
        }
        globalTags {
            ...globalTagsFields
        }
        glossaryTerms {
            ...glossaryTerms
        }
        platform {
            ...platformFields
        }
        dataPlatformInstance {
            ...dataPlatformInstanceFields
        }
        domain {
            ...entityDomain
        }
        ...entityDataProduct
        parentContainers {
            ...parentContainersFields
        }
    }
    ... on GlossaryTerm {
        name
        hierarchicalName
        governanceFlags {
            flags {
                auditStamp {
                    actor
                    time
                }
                doc
                name
                value
            }
        }
        subTypes {
            typeNames
        }
        properties {
            name
            description
            termSource
            sourceRef
            sourceUrl
            rawSchema
            customProperties {
                key
                value
            }
        }
        parentNodes {
            ...parentNodesFields
        }
        domain {
            ...entityDomain
        }
    }
    ... on GlossaryNode {
        ...glossaryNode
        parentNodes {
            ...parentNodesFields
        }
    }
    ... on Domain {
        properties {
            name
            description
        }
        ownership {
            ...ownershipFields
        }
        parentDomains {
            ...parentDomainsFields
        }
        ...domainEntitiesFields
    }
    ... on Container {
        properties {
            name
            description
            externalUrl
        }
        platform {
            ...platformFields
        }
        dataPlatformInstance {
            ...dataPlatformInstanceFields
        }
        ownership {
