query getEntityLineage($urn: String!, $separateSiblings: Boolean, $showColumns: Boolean!, $startTimeMillis: Long, $endTimeMillis: Long, $excludeUpstream: Boolean = false, $excludeDownstream: Boolean = false) {
  entity(urn: $urn) {
    urn
    type
    ...lineageNodeProperties
    ...canEditLineageFragment
    ... on Dataset {
      schemaMetadata(version: 0) @include(if: $showColumns) {
        ...schemaMetadataFields
        __typename
      }
      siblings {
        isPrimary
        siblings {
          urn
          type
          ... on Dataset {
            exists
            __typename
          }
          ...lineageNodeProperties
          __typename
        }
        __typename
      }
      __typename
    }
    ... on Chart {
      inputFields @include(if: $showColumns) {
        ...inputFieldsFields
        __typename
      }
      __typename
    }
    ... on EntityWithRelationships {
      upstream: lineage(
        input: {direction: UPSTREAM, start: 0, count: 100, separateSiblings: $separateSiblings, startTimeMillis: $startTimeMillis, endTimeMillis: $endTimeMillis}
      ) @skip(if: $excludeUpstream) {
        ...fullLineageResults
        __typename
      }
      downstream: lineage(
        input: {direction: DOWNSTREAM, start: 0, count: 100, separateSiblings: $separateSiblings, startTimeMillis: $startTimeMillis, endTimeMillis: $endTimeMillis}
      ) @skip(if: $excludeDownstream) {
        ...fullLineageResults
        __typename
      }
      __typename
    }
    __typename
  }
}

